def translate(text):
    log = []
    for old, new in TH:
        count = text.count(old)
        if count == 0:
            log.append((old[:50], 0))
            continue
        text = text.replace(old, new)
        log.append((old[:50], count))
    return text, log


def main():
    print("=== Build Bilingual Homepage (Thai root + /eng/) ===\n")

    if not ROOT.exists():
        print("ERROR: index.html not found. Run from /Users/anies/Downloads/arc-site")
        sys.exit(1)

    dirty = subprocess.run(["git", "status", "--porcelain", "--untracked-files=no"],
                            cwd=REPO, capture_output=True, text=True).stdout.strip()
    if dirty:
        print("ERROR: working tree not clean. Commit or stash first.")
        print(dirty)
        sys.exit(1)

    original = ROOT.read_text(encoding="utf-8", errors="ignore")

    print("Step 1: Save current English homepage to /eng/")
    ENG_DIR.mkdir(exist_ok=True)
    eng_text = original
    eng_text = eng_text.replace(
        '<link rel="canonical" href="https://www.arc-international-edu.com/">',
        '<link rel="canonical" href="https://www.arc-international-edu.com/eng/">\n  <link rel="alternate" hreflang="th" href="https://www.arc-international-edu.com/">\n  <link rel="alternate" hreflang="en" href="https://www.arc-international-edu.com/eng/">\n  <link rel="alternate" hreflang="x-default" href="https://www.arc-international-edu.com/">'
    )
    eng_text = eng_text.replace(
        '<meta property="og:url" content="https://www.arc-international-edu.com/">',
        '<meta property="og:url" content="https://www.arc-international-edu.com/eng/">'
    )
    eng_text = eng_text.replace(
        '<a href="mailto:arc.international.edu@gmail.com" class="nav-cta">Get in Touch</a>',
        TH_BTN_DESKTOP + '\n  <a href="mailto:arc.international.edu@gmail.com" class="nav-cta">Get in Touch</a>',
        1
    )
    eng_text = eng_text.replace(
        '<a href="#programs" onclick="closeMobileNav()">Programs</a>',
        TH_BTN_MOBILE + '\n  <a href="#programs" onclick="closeMobileNav()">Programs</a>',
        1
    )
    ENG_FILE.write_text(eng_text, encoding="utf-8")
    print(f"  written: eng/index.html ({len(eng_text)} bytes)\n")

    print("Step 2: Translate homepage to Thai")
    thai_text, log = translate(original)

    thai_text = thai_text.replace(
        '<link rel="canonical" href="https://www.arc-international-edu.com/">',
        '<link rel="canonical" href="https://www.arc-international-edu.com/">\n  <link rel="alternate" hreflang="th" href="https://www.arc-international-edu.com/">\n  <link rel="alternate" hreflang="en" href="https://www.arc-international-edu.com/eng/">\n  <link rel="alternate" hreflang="x-default" href="https://www.arc-international-edu.com/">'
    )

    missed = [l for l in log if l[1] == 0]
    hit = [l for l in log if l[1] > 0]
    print(f"  {len(hit)} string(s) translated, {len(missed)} not found (may already differ)")
    if missed:
        print("  Not found (first 50 chars):")
        for m, _ in missed[:15]:
            print(f"    - {m}")
        if len(missed) > 15:
            print(f"    ... and {len(missed) - 15} more")

    ROOT.write_text(thai_text, encoding="utf-8")
    print(f"\n  written: index.html ({len(thai_text)} bytes, Thai)\n")

    print("Step 3: Update sitemap.xml")
    sf = REPO / "sitemap.xml"
    if sf.exists():
        stext = sf.read_text(encoding="utf-8", errors="ignore")
        eng_url = f"{DOMAIN}/eng/"
        if eng_url not in stext:
            today = datetime.date.today().isoformat()
            entry = f"  <url><loc>{eng_url}</loc><lastmod>{today}</lastmod></url>"
            stext = stext.replace("</urlset>", entry + "\n</urlset>")
            sf.write_text(stext, encoding="utf-8")
            print("  added /eng/ to sitemap.xml")
        else:
            print("  /eng/ already in sitemap.xml")

    print("\nCommitting and pushing...")
    r = subprocess.run(["git", "add", "-A"], cwd=REPO)
    if r.returncode != 0:
        sys.exit(1)
    r = subprocess.run(["git", "commit", "-m", "Add Thai homepage at root, move English to /eng/"], cwd=REPO)
    if r.returncode != 0:
        print("Nothing to commit or commit failed.")
        sys.exit(1)
    r = subprocess.run(["git", "push"], cwd=REPO)
    if r.returncode != 0:
        sys.exit(1)

    print("\n=== DONE ===")
    print(f"Thai homepage: {DOMAIN}/")
    print(f"English homepage: {DOMAIN}/eng/")
    print("\nVerify in ~1 min:")
    print(f"  curl -s -o /dev/null -w '%{{http_code}}\\n' {DOMAIN}/")
    print(f"  curl -s -o /dev/null -w '%{{http_code}}\\n' {DOMAIN}/eng/")
    print("\nThen check Google Search Console -> URL Inspection -> Request Indexing for /eng/")


if __name__ == "__main__":
    main()
